class Solution {
  private int n;
  private long[] countBit, lengthBit;
  private long totalCount, totalLength;
  private TreeSet<Integer> bad; // i is bad when colors[i] == colors[i + 1]

  public List<Integer> numberOfAlternatingGroups(int[] colors, int[][] queries) {
    n = colors.length;
    countBit = new long[n + 1];
    lengthBit = new long[n + 1];
    bad = new TreeSet<>();
    for (int i = 0; i < n; i++) if (colors[i] == colors[(i + 1) % n]) bad.add(i);
    if (bad.size() == 1) addRun(n, 1);
    else if (bad.size() > 1) {
      Integer prev = bad.last();
      for (int cur : bad) {
        addRun(gap(prev, cur), 1);
        prev = cur;
      }
    }
    List<Integer> answer = new ArrayList<>();
    for (int[] q : queries) {
      if (q[0] == 1) {
        answer.add(count(q[1]));
        continue;
      }
      int p = q[1];
      if (colors[p] == q[2]) continue;
      colors[p] = q[2];
      for (int edge : new int[] {(p - 1 + n) % n, p}) {
        boolean nowBad = colors[edge] == colors[(edge + 1) % n];
        if (nowBad && !bad.contains(edge)) addBad(edge);
        else if (!nowBad && bad.contains(edge)) removeBad(edge);
      }
    }
    return answer;
  }

  // number of tiles between bad edge a (exclusive) and bad edge b (inclusive), going around the
  // circle
  private int gap(int a, int b) {
    int d = ((b - a) % n + n) % n;
    return d == 0 ? n : d;
  }

  private Integer circularLower(int i) {
    Integer p = bad.lower(i);
    return p != null ? p : bad.last();
  }

  private Integer circularHigher(int i) {
    Integer p = bad.higher(i);
    return p != null ? p : bad.first();
  }

  private void addBad(int i) {
    if (bad.isEmpty()) {
      addRun(n, 1);
    } else {
      int pred = circularLower(i), succ = circularHigher(i);
      addRun(gap(pred, succ), -1);
      addRun(gap(pred, i), 1);
      addRun(gap(i, succ), 1);
    }
    bad.add(i);
  }

  private void removeBad(int i) {
    bad.remove(i);
    if (bad.isEmpty()) {
      addRun(n, -1);
      return;
    }
    // the two runs around i merge into one (bad is non-empty, so neighbours exist)
    Integer pred = bad.lower(i), succ = bad.higher(i);
    if (pred == null) pred = bad.last();
    if (succ == null) succ = bad.first();
    addRun(gap(pred, i), -1);
    addRun(gap(i, succ), -1);
    addRun(gap(pred, succ), 1);
  }

  private void addRun(int length, int sign) {
    totalCount += sign;
    totalLength += (long) sign * length;
    for (int i = length; i <= n; i += i & -i) {
      countBit[i] += sign;
      lengthBit[i] += (long) sign * length;
    }
  }

  // groups of size k: every run of length L >= k contributes L - k + 1
  private int count(int k) {
    if (bad.isEmpty()) return n;
    long smallCount = 0, smallLength = 0;
    for (int i = k - 1; i > 0; i -= i & -i) {
      smallCount += countBit[i];
      smallLength += lengthBit[i];
    }
    long runs = totalCount - smallCount, tiles = totalLength - smallLength;
    return (int) (tiles - (long) (k - 1) * runs);
  }
}
